from pathlib import Path
import json,hashlib,re,markdown,difflib
from PIL import Image
R=Path(__file__).resolve().parents[4];O=Path(__file__).resolve().parent
M=R/'commons/maps/Boolean_Colour_Spaces_II'
A=R/'commons/artifacts/boolean_colour_chamber'
S=R/'ada_run/boolean-more-spaces-isolated'
checks=json.loads((O/'runtime.json').read_text(encoding='utf-8'))['checks']
assert all(c['pass'] for c in checks)
files=[]
for p in sorted(A.iterdir()):
 if p.suffix in ('.gd','.gdshader','.tscn'):
  assert p.read_bytes()==(S/p.relative_to(R)).read_bytes(),p
  files.append({'file':p.relative_to(R).as_posix(),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'matches_tested_copy':True})
for p in sorted(M.iterdir()):
 if p.is_file():files.append({'file':p.relative_to(R).as_posix(),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
images=[]
for p in sorted(O.glob('*.png')):
 with Image.open(p) as im: im.load();assert im.size==(1440,900)
 images.append({'file':p.name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
assert len(images)==14
(O/'manifest.json').write_text(json.dumps({'scope':'Isolated desktop artifact; map loader and headset untested','passed_records':len(checks),'source':files,'images':images},indent=2),encoding='utf-8')
for p in (O/'before').rglob('*'):
 if p.is_file():
  relative=p.relative_to(O/'before');current=R/relative
  diff=''.join(difflib.unified_diff(p.read_text(encoding='utf-8').splitlines(True),current.read_text(encoding='utf-8').splitlines(True),fromfile='before/'+relative.as_posix(),tofile=relative.as_posix()))
  (O/(p.stem+'.diff')).write_text(diff,encoding='utf-8')
style=re.search(r'<style>(.*?)</style>',(O.parent/'2026-09-24-boolean-colour-spaces/index.html').read_text(encoding='utf-8'),re.S).group(1)
reading=markdown.markdown((M/'final.md').read_text(encoding='utf-8'));reading=re.sub(r'<h1>.*?</h1>','',reading,count=1)
rooms=[('ring','04','The way around','AMBER / TORUS','A torus removed from a block leaves a core. Follow either half of the ring: the centre hides the other route until walking brings it back into view.'),('cross','05','A room with another direction','PEARL / CROSSING CYLINDERS','Two horizontal cuts meet beneath higher openings. Turn at the crossing, step outside through a side passage, and return.'),('fold','06','The enclosure leans','CHROME / TILTED PLANES','Alternately tilted boxes make sharp changes in the wall and ceiling. The floor stays level while the enclosure inclines.')]
roomhtml=''
for name,n,title,tag,desc in rooms:
 roomhtml+=f'<section id="{name}" class="room"><div class="roomhead"><span class="number">{n}</span><div><p class="eyebrow">{tag}</p><h2>{title}</h2><p>{desc}</p></div></div><a href="{name}-inside.png"><img width="1440" height="900" loading="lazy" src="{name}-inside.png" alt="Inside the {name} construction"></a><details><summary>Entrance and ceiling</summary><div class="pair"><figure><a href="{name}-entry.png"><img loading="lazy" src="{name}-entry.png" alt="Entrance to {name}"></a><figcaption>Approach from outside</figcaption></figure><figure><a href="{name}-ceiling.png"><img loading="lazy" src="{name}-ceiling.png" alt="Ceiling of {name}"></a><figcaption>Looking into the upper cut</figcaption></figure></div></details></section>'
finishes=''.join(f'<figure><a href="surface-{i}.png"><img loading="lazy" src="surface-{i}.png" alt="Crossing vault in {name}"></a><figcaption>{name}</figcaption></figure>' for i,name in enumerate(['Pearl','Amber','Chrome','Chalk']))
page=r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Around, across, through | Ada Research</title><style>__STYLE__</style></head><body><header><p class="eyebrow">Ada Research / Boolean spaces 04—06 / 24 September 2026</p><h1>Around,<br>across,<br>through.</h1><p class="lead">The cut changes where a body can go. Three more spaces, three different ways to move.</p><nav aria-label="Page sections"><a href="#ring">The loop</a><a href="#cross">The crossing</a><a href="#fold">The fold</a><a href="#finishes">Four finishes</a><a href="#play">Walk inside</a><a href="#reading">Read the hall</a></nav><a href="cross-inside.png"><img width="1440" height="900" src="cross-inside.png" alt="Native Godot view inside the pearl crossing vault"></a><p class="caption">The crossing vault. Native render of the playable Godot artifact.</p></header><main><div class="intro"><p>The first three spaces followed a path, occupied an intersection and hollowed a joined shell. These additions introduce a route around a surviving core, lateral departures, and inclined planar boundaries.</p><p>All six share the same four finishes. Keep the construction and change its appearance; carry a finish into another construction. The body has something different to do in each.</p><p><a href="../2026-09-24-facade-room-and-cast/index.html">Next: enter the facade, then walk around its interior as a solid form</a></p><p><a href="../2026-09-24-boolean-colour-spaces/index.html">Return to spaces 01–03</a></p></div>__ROOMS__<section id="finishes"><p class="eyebrow">Same crossing / same camera</p><h2>Four ways to see the cut.</h2><p>PEARL, AMBER, CHROME and CHALK change the shader and local light colours. DRIFT slowly advances the surface pattern; press it again to hold the phase. The physical boundary stays fixed.</p><div class="finishes">__FINISHES__</div></section><section id="play" class="play"><p class="eyebrow">Playable study / six constructions in total</p><h2>Take the other route.</h2><p>Open <code>commons/artifacts/boolean_colour_chamber/more_spaces.tscn</code> in Godot and press F6. WASD moves; the mouse looks; click the entrance material controls. Keys 1, 2 and 3 return to the loop, crossing and fold entrances. Escape releases the mouse.</p><p>The new map is <code>Boolean_Colour_Spaces_II</code>. A new portal links it from the first study map, with a return portal in the second. The separate desktop scene has continuous surrounding ground for the side exits.</p><p><a href="/compose/sources?map=Boolean_Colour_Spaces_II&amp;doc=final">Open the new chapter in Sources</a></p></section><section class="reading" id="reading"><p class="eyebrow">Study chapter / final.md</p>__READING__</section><section class="evidence"><h2>Checked with a body.</h2><p>The isolated desktop probe passed both halves of the loop, the main crossing in both directions, both side exits and returns, and the folded passage in both directions. A 1.8 m capsule stayed supported throughout. The central core blocks a direct shortcut. Material controls, unchanged geometry and holding the stopped shader phase also passed.</p><p>There are 79 passing records, including image writes and mesh records. Source hashes match the production files. These native views are used in the chapter as well. Full museum-loader and headset checks remain open.</p><details><summary>Source, comparisons and evidence</summary><p><a href="DECISIONS.md">Construction decisions</a> · <a href="runtime.json">Runtime checks</a> · <a href="manifest.json">Source and image hashes</a> · <a href="boolean_colour_chamber.diff">Generator changes</a> · <a href="study.diff">Study changes</a></p><p>The new constructions are staged in development maps, outside the canonical Boolean sequence. Existing halls and artifacts remain in place. Original files affected by this extension are preserved in the before folder.</p><p>The ring adds a toroidal cutter; the crossing subtracts a union of cylinders; the fold subtracts alternating tilted boxes. Surface shaders do not displace the boundary. No generated raster imagery is used.</p></details></section></main><footer>Ada Research · Six Boolean constructions · Working spaces and shared book illustrations.</footer></body></html>"""
page=page.replace('__STYLE__',style).replace('__ROOMS__',roomhtml).replace('__FINISHES__',finishes).replace('__READING__',reading)
(O/'index.html').write_text(page,encoding='utf-8')
print('Published three new spaces;',len(checks),'passing records;',len(images),'native captures')
